impl < 'a , 'b > Builder < 'a , 'b > { # [doc = " Create a new `Builder`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Create a named temporary file and write some data into it:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ffi::OsStr;"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .prefix(\"my-temporary-note\")"] # [doc = "     .suffix(\".txt\")"] # [doc = "     .rand_bytes(5)"] # [doc = "     .tempfile()?;"] # [doc = ""] # [doc = " let name = named_tempfile"] # [doc = "     .path()"] # [doc = "     .file_name().and_then(OsStr::to_str);"] # [doc = ""] # [doc = " if let Some(name) = name {"] # [doc = "     assert!(name.starts_with(\"my-temporary-note\"));"] # [doc = "     assert!(name.ends_with(\".txt\"));"] # [doc = "     assert_eq!(name.len(), \"my-temporary-note.txt\".len() + 5);"] # [doc = " }"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Create a temporary directory and add a file to it:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::io::Write;"] # [doc = " use std::fs::File;"] # [doc = " use std::ffi::OsStr;"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let dir = Builder::new()"] # [doc = "     .prefix(\"my-temporary-dir\")"] # [doc = "     .rand_bytes(5)"] # [doc = "     .tempdir()?;"] # [doc = ""] # [doc = " let file_path = dir.path().join(\"my-temporary-note.txt\");"] # [doc = " let mut file = File::create(file_path)?;"] # [doc = " writeln!(file, \"Brian was here. Briefly.\")?;"] # [doc = ""] # [doc = " // By closing the `TempDir` explicitly, we can check that it has"] # [doc = " // been deleted successfully. If we don't close it explicitly,"] # [doc = " // the directory will still be deleted when `dir` goes out"] # [doc = " // of scope, but we won't know whether deleting the directory"] # [doc = " // succeeded."] # [doc = " drop(file);"] # [doc = " dir.close()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Create a temporary directory with a chosen prefix under a chosen folder:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let dir = Builder::new()"] # [doc = "     .prefix(\"my-temporary-dir\")"] # [doc = "     .tempdir_in(\"folder-with-tempdirs\")?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [must_use] pub fn new () -> Self { Self :: default () } # [doc = " Set a custom filename prefix."] # [doc = ""] # [doc = " Path separators are legal but not advisable."] # [doc = " Default: `.tmp`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .prefix(\"my-temporary-note\")"] # [doc = "     .tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn prefix < S : AsRef < OsStr > + ? Sized > (& mut self , prefix : & 'a S) -> & mut Self { self . prefix = prefix . as_ref () ; self } # [doc = " Set a custom filename suffix."] # [doc = ""] # [doc = " Path separators are legal but not advisable."] # [doc = " Default: empty."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .suffix(\".txt\")"] # [doc = "     .tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn suffix < S : AsRef < OsStr > + ? Sized > (& mut self , suffix : & 'b S) -> & mut Self { self . suffix = suffix . as_ref () ; self } # [doc = " Set the number of random bytes."] # [doc = ""] # [doc = " Default: `6`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .rand_bytes(5)"] # [doc = "     .tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn rand_bytes (& mut self , rand : usize) -> & mut Self { self . random_len = rand ; self } # [doc = " Configure the file to be opened in append-only mode."] # [doc = ""] # [doc = " Default: `false`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .append(true)"] # [doc = "     .tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn append (& mut self , append : bool) -> & mut Self { self . append = append ; self } # [doc = " Set the permissions for the new temporary file/directory."] # [doc = ""] # [doc = " # Platform Notes"] # [doc = ""] # [doc = " ## Windows"] # [doc = ""] # [doc = " This setting is only fully-supported on unix-like platforms. On Windows, if this method is"] # [doc = " called with a [`Permissions`] object where `permissions.readonly` returns true, creating"] # [doc = " temporary files and directories will fail with an error."] # [doc = ""] # [doc = " ## Unix"] # [doc = ""] # [doc = " On unix-like systems, the actual permission bits set on the tempfile or tempdir will be"] # [doc = " affected by the `umask` applied by the underlying syscall. The actual permission bits are"] # [doc = " calculated via `permissions & !umask`. In other words, depending on your umask, the"] # [doc = " permissions of the created file may be more restrictive (but never more permissive) than the"] # [doc = " ones you specified."] # [doc = ""] # [doc = " Permissions default to `0o600` for tempfiles and `0o777` for tempdirs. Note, this doesn't"] # [doc = " include effects of the current `umask`. For example, combined with the standard umask"] # [doc = " `0o022`, the defaults yield `0o600` for tempfiles and `0o755` for tempdirs."] # [doc = ""] # [doc = " ## WASI"] # [doc = ""] # [doc = " While custom permissions are allowed on WASI, they will be ignored as the platform has no"] # [doc = " concept of permissions or file modes (or multiple users for that matter)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Create a named temporary file that is world-readable."] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(unix)]"] # [doc = " # {"] # [doc = " use tempfile::Builder;"] # [doc = " use std::os::unix::fs::PermissionsExt;"] # [doc = ""] # [doc = " let all_read_write = std::fs::Permissions::from_mode(0o666);"] # [doc = " let tempfile = Builder::new().permissions(all_read_write).tempfile()?;"] # [doc = ""] # [doc = " // Check that this worked and that the file is world-readable."] # [doc = " //"] # [doc = " // NOTE: the file likely won't actually be created with 0o666 permissions because it's"] # [doc = " // restricted by the user's umask."] # [doc = " //"] # [doc = " // NOTE: This test will fail if the user's umask is, e.g., 0o066."] # [doc = " let actual_permissions = tempfile.path().metadata()?.permissions();"] # [doc = " assert_eq!(actual_permissions.mode() & 0o044, 0o044);"] # [doc = " # }"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Create a named temporary directory that is restricted to the owner."] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(unix)]"] # [doc = " # {"] # [doc = " use tempfile::Builder;"] # [doc = " use std::os::unix::fs::PermissionsExt;"] # [doc = ""] # [doc = " let owner_rwx = std::fs::Permissions::from_mode(0o700);"] # [doc = " let tempdir = Builder::new().permissions(owner_rwx).tempdir()?;"] # [doc = " let actual_permissions = tempdir.path().metadata()?.permissions();"] # [doc = " assert_eq!("] # [doc = "     actual_permissions.mode() & !0o170000,"] # [doc = "     0o700,"] # [doc = "     \"we get the narrow permissions we asked for\""] # [doc = " );"] # [doc = " # }"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn permissions (& mut self , permissions : Permissions) -> & mut Self { self . permissions = Some (permissions) ; self } # [doc = " Disable cleanup of the file/folder to even when the [`NamedTempFile`]/[`TempDir`] goes out"] # [doc = " of scope. Prefer [`NamedTempFile::keep`] and [`TempDir::keep`] where possible;"] # [doc = " `disable_cleanup` is provided for testing & debugging."] # [doc = ""] # [doc = " By default, the file/folder is automatically cleaned up in the destructor of"] # [doc = " [`NamedTempFile`]/[`TempDir`]. When `disable_cleanup` is set to `true`, this behavior is"] # [doc = " suppressed. If you wish to disable cleanup after creating a temporary file/directory, call"] # [doc = " [`NamedTempFile::disable_cleanup`] or [`TempDir::disable_cleanup`]."] # [doc = ""] # [doc = " # Warnings"] # [doc = ""] # [doc = " On some platforms (for now, only Windows), temporary files are marked with a special"] # [doc = " \"temporary file\" (`FILE_ATTRIBUTE_TEMPORARY`) attribute. Disabling cleanup _will not_ unset"] # [doc = " this attribute while calling [`NamedTempFile::keep`] will."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let named_tempfile = Builder::new()"] # [doc = "     .disable_cleanup(true)"] # [doc = "     .tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn disable_cleanup (& mut self , disable_cleanup : bool) -> & mut Self { self . disable_cleanup = disable_cleanup ; self } # [doc = " Deprecated alias for [`Builder::disable_cleanup`]."] # [deprecated = "Use Builder::disable_cleanup"] pub fn keep (& mut self , keep : bool) -> & mut Self { self . disable_cleanup (keep) } # [doc = " Create the named temporary file."] # [doc = ""] # [doc = " # Security"] # [doc = ""] # [doc = " See [the security][security] docs on `NamedTempFile`."] # [doc = ""] # [doc = " # Resource leaking"] # [doc = ""] # [doc = " See [the resource leaking][resource-leaking] docs on `NamedTempFile`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If the file cannot be created, `Err` is returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let tempfile = Builder::new().tempfile()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [security]: struct.NamedTempFile.html#security"] # [doc = " [resource-leaking]: struct.NamedTempFile.html#resource-leaking"] pub fn tempfile (& self) -> io :: Result < NamedTempFile > { self . tempfile_in (env :: temp_dir ()) } # [doc = " Create the named temporary file in the specified directory."] # [doc = ""] # [doc = " # Security"] # [doc = ""] # [doc = " See [the security][security] docs on `NamedTempFile`."] # [doc = ""] # [doc = " # Resource leaking"] # [doc = ""] # [doc = " See [the resource leaking][resource-leaking] docs on `NamedTempFile`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If the file cannot be created, `Err` is returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let tempfile = Builder::new().tempfile_in(\"./\")?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [security]: struct.NamedTempFile.html#security"] # [doc = " [resource-leaking]: struct.NamedTempFile.html#resource-leaking"] pub fn tempfile_in < P : AsRef < Path > > (& self , dir : P) -> io :: Result < NamedTempFile > { util :: create_helper (dir . as_ref () , self . prefix , self . suffix , self . random_len , | path | { file :: create_named (path , OpenOptions :: new () . append (self . append) , self . permissions . as_ref () , self . disable_cleanup ,) } ,) } # [doc = " Attempts to make a temporary directory inside of [`env::temp_dir()`] whose"] # [doc = " name will have the prefix, `prefix`. The directory and"] # [doc = " everything inside it will be automatically deleted once the"] # [doc = " returned `TempDir` is destroyed."] # [doc = ""] # [doc = " # Resource leaking"] # [doc = ""] # [doc = " See [the resource leaking][resource-leaking] docs on `TempDir`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If the directory can not be created, `Err` is returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let tmp_dir = Builder::new().tempdir()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [resource-leaking]: struct.TempDir.html#resource-leaking"] pub fn tempdir (& self) -> io :: Result < TempDir > { self . tempdir_in (env :: temp_dir ()) } # [doc = " Attempts to make a temporary directory inside of `dir`."] # [doc = " The directory and everything inside it will be automatically"] # [doc = " deleted once the returned `TempDir` is destroyed."] # [doc = ""] # [doc = " # Resource leaking"] # [doc = ""] # [doc = " See [the resource leaking][resource-leaking] docs on `TempDir`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If the directory can not be created, `Err` is returned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let tmp_dir = Builder::new().tempdir_in(\"./\")?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [resource-leaking]: struct.TempDir.html#resource-leaking"] pub fn tempdir_in < P : AsRef < Path > > (& self , dir : P) -> io :: Result < TempDir > { util :: create_helper (dir . as_ref () , self . prefix , self . suffix , self . random_len , | path | dir :: create (path , self . permissions . as_ref () , self . disable_cleanup) ,) } # [doc = " Attempts to create a temporary file (or file-like object) using the"] # [doc = " provided closure. The closure is passed a temporary file path and"] # [doc = " returns an [`std::io::Result`]. The path provided to the closure will be"] # [doc = " inside of [`env::temp_dir()`]. Use [`Builder::make_in`] to provide"] # [doc = " a custom temporary directory. If the closure returns one of the"] # [doc = " following errors, then another randomized file path is tried:"] # [doc = "  - [`std::io::ErrorKind::AlreadyExists`]"] # [doc = "  - [`std::io::ErrorKind::AddrInUse`]"] # [doc = ""] # [doc = " This can be helpful for taking full control over the file creation, but"] # [doc = " leaving the temporary file path construction up to the library. This"] # [doc = " also enables creating a temporary UNIX domain socket, since it is not"] # [doc = " possible to bind to a socket that already exists."] # [doc = ""] # [doc = " Note that [`Builder::append`] is ignored when using [`Builder::make`]."] # [doc = ""] # [doc = " # Security"] # [doc = ""] # [doc = " This has the same [security implications][security] as"] # [doc = " [`NamedTempFile`], but with additional caveats. Specifically, it is up"] # [doc = " to the closure to ensure that the file does not exist and that such a"] # [doc = " check is *atomic*. Otherwise, a [time-of-check to time-of-use"] # [doc = " bug][TOCTOU] could be introduced."] # [doc = ""] # [doc = " For example, the following is **not** secure:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::fs::File;"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " // This is NOT secure!"] # [doc = " let tempfile = Builder::new().make(|path| {"] # [doc = "     if path.is_file() {"] # [doc = "         return Err(std::io::ErrorKind::AlreadyExists.into());"] # [doc = "     }"] # [doc = ""] # [doc = "     // Between the check above and the usage below, an attacker could"] # [doc = "     // have replaced `path` with another file, which would get truncated"] # [doc = "     // by `File::create`."] # [doc = ""] # [doc = "     File::create(path)"] # [doc = " })?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Note that simply using [`std::fs::File::create`] alone is not correct"] # [doc = " because it does not fail if the file already exists:"] # [doc = ""] # [doc = " ```"] # [doc = " use tempfile::Builder;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " // This could overwrite an existing file!"] # [doc = " let tempfile = Builder::new().make(|path| File::create(path))?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = " For creating regular temporary files, use [`Builder::tempfile`] instead"] # [doc = " to avoid these problems. This function is meant to enable more exotic"] # [doc = " use-cases."] # [doc = ""] # [doc = " # Resource leaking"] # [doc = ""] # [doc = " See [the resource leaking][resource-leaking] docs on `NamedTempFile`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If the closure returns any error besides"] # [doc = " [`std::io::ErrorKind::AlreadyExists`] or"] # [doc = " [`std::io::ErrorKind::AddrInUse`], then `Err` is returned."] # [doc = ""] # [doc = " # Examples"] # [doc = " ```"] # [doc = " # #[cfg(unix)]"] # [doc = " # {"] # [doc = " use std::os::unix::net::UnixListener;"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " let tempsock = Builder::new().make(|path| UnixListener::bind(path))?;"] # [doc = " # }"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [TOCTOU]: https://en.wikipedia.org/wiki/Time-of-check_to_time-of-use"] # [doc = " [security]: struct.NamedTempFile.html#security"] # [doc = " [resource-leaking]: struct.NamedTempFile.html#resource-leaking"] pub fn make < F , R > (& self , f : F) -> io :: Result < NamedTempFile < R > > where F : FnMut (& Path) -> io :: Result < R > , { self . make_in (env :: temp_dir () , f) } # [doc = " This is the same as [`Builder::make`], except `dir` is used as the base"] # [doc = " directory for the temporary file path."] # [doc = ""] # [doc = " See [`Builder::make`] for more details and security implications."] # [doc = ""] # [doc = " # Examples"] # [doc = " ```"] # [doc = " # #[cfg(unix)]"] # [doc = " # {"] # [doc = " use tempfile::Builder;"] # [doc = " use std::os::unix::net::UnixListener;"] # [doc = ""] # [doc = " let tempsock = Builder::new().make_in(\"./\", |path| UnixListener::bind(path))?;"] # [doc = " # }"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] pub fn make_in < F , R , P > (& self , dir : P , mut f : F) -> io :: Result < NamedTempFile < R > > where F : FnMut (& Path) -> io :: Result < R > , P : AsRef < Path > , { util :: create_helper (dir . as_ref () , self . prefix , self . suffix , self . random_len , move | path | { Ok (NamedTempFile :: from_parts (f (& path) ? , TempPath :: new (path , self . disable_cleanup) ,)) } ,) } }